{
  "findings": [
    {
      "ref": "[D522]",
      "area": "age_gating",
      "claim": "A parent reports that Snapchat's age verification is minimal and relies only on a birth date with no real checks, allowing kids to fake their age.",
      "stance": "risk",
      "quote": "Snapchat requires users to be at least 13 years old, but it's actually required to under U.S. privacy laws (COPPA). In reality, Snapchat's age verification is minimal. It only asks for a birth date at signup, with no real checks behind it. Kids who want to join early can easily fake their age—and many do."
    },
    {
      "ref": "[D522]",
      "area": "age_gating",
      "claim": "A parent reports that Snapchat locks in the original birth date after signup, preventing users from editing it to bypass age protections.",
      "stance": "mitigation",
      "quote": "Snapchat also locks in the original birth date after teens sign up, so they can't edit it later to \"age up\" and bypass protections."
    },
    {
      "ref": "[D522]",
      "area": "contact",
      "claim": "A parent reports that Snapchat allows strangers to message teens unless set to \"My Friends\", and that this contact can be turned off.",
      "stance": "risk",
      "quote": "Who Can Contact Me: Set this to \"My Friends\" so only approved contacts can send messages. Remind your teen to avoid accepting friend requests from people they don't know well."
    },
    {
      "ref": "[D522]",
      "area": "contact",
      "claim": "A parent reports that Snapchat's default setting for who can view Stories is limited to friends, but this can be adjusted.",
      "stance": "mitigation",
      "quote": "Who Can View My Story: Limit this to \"My Friends\" to control who can see daily updates and photos."
    },
    {
      "ref": "[D522]",
      "area": "contact",
      "claim": "A parent reports that Snapchat restricts friend suggestions and random friend requests for younger users.",
      "stance": "mitigation",
      "quote": "They won't appear in Quick Add recommendations for people they don't know, which helps limit random friend requests."
    },
    {
      "ref": "[D522]",
      "area": "money",
      "claim": "A parent reports that Snapchat's Discover and Spotlight content includes marketed items and influencer monetization that may pressure teens to spend.",
      "stance": "risk",
      "quote": "Creator influence: Snapchat now offers a monetization program that lets eligible creators earn money from ads in their Stories and Spotlight posts. Teens who see influencers getting paid for views may feel pressure to post more often, chase viral moments, or spend more time curating content to stand out."
    },
    {
      "ref": "[D522]",
      "area": "data",
      "claim": "A parent reports that Snapchat collects data for ads and may share it with third parties, but does not allow full deletion.",
      "stance": "risk",
      "quote": "Snapchat's Discover and Spotlight is filtered to reduce exposure to mature or inappropriate material, but filters are not always perfect."
    },
    {
      "ref": "[D522]",
      "area": "developer_record",
      "claim": "A parent reports that Snapchat has faced regulatory scrutiny for minimal age verification and privacy practices.",
      "stance": "risk",
      "quote": "Snapchat requires users to be at least 13 years old, but it's actually required to under U.S. privacy laws (COPPA). In reality, Snapchat's age verification is minimal. It only asks for a birth date at signup, with no real checks behind it. Kids who want to join early can easily fake their age—and many do."
    }
  ]
}
